-- 1. TABEL TOKENS (Manajemen Token Sesi Seminar)
create table if not exists public.tokens (
    id uuid primary key default gen_random_uuid(),
    token text not null unique,
    title text default 'Token Sesi Seminar',
    duration_minutes integer not null default 60,
    expires_at timestamptz not null,
    is_active boolean not null default true,
    created_at timestamptz not null default now()
);

create index if not exists idx_tokens_token on public.tokens(token);
create index if not exists idx_tokens_expires_at on public.tokens(expires_at);

-- 2. TABEL PARTICIPANTS (Database 148 Peserta Terdaftar)
create table if not exists public.participants (
    id bigint generated by default as identity primary key,
    norm_phone text not null unique,
    raw_phone text not null,
    name text not null,
    institution text,
    major text,
    proof_url text,
    created_at timestamptz not null default now()
);

create index if not exists idx_participants_norm_phone on public.participants(norm_phone);

-- 3. TABEL ACCESS_LOGS (Catatan Presensi & Upaya Akses Formulir Realtime)
create table if not exists public.access_logs (
    id bigint generated by default as identity primary key,
    token text not null,
    norm_phone text not null,
    participant_name text,
    status text not null, -- 'granted', 'token_expired', 'token_invalid', 'unregistered_phone'
    user_agent text,
    accessed_at timestamptz not null default now()
);

create index if not exists idx_access_logs_phone on public.access_logs(norm_phone);
create index if not exists idx_access_logs_token on public.access_logs(token);
create index if not exists idx_access_logs_accessed_at on public.access_logs(accessed_at desc);

-- ==============================================================================
-- KEBIJAKAN ROW LEVEL SECURITY (RLS)
-- Mengizinkan anon key untuk membaca, menulis, dan menghapus log/token
-- ==============================================================================

alter table public.tokens enable row level security;
alter table public.participants enable row level security;
alter table public.access_logs enable row level security;

-- Policies untuk tokens
drop policy if exists "Anon full access on tokens" on public.tokens;
create policy "Anon full access on tokens" on public.tokens
    for all to anon using (true) with check (true);

-- Policies untuk participants
drop policy if exists "Anon full access on participants" on public.participants;
create policy "Anon full access on participants" on public.participants
    for all to anon using (true) with check (true);

-- Policies untuk access_logs (bisa select, insert, delete untuk bersihkan log)
drop policy if exists "Anon full access on access_logs" on public.access_logs;
drop policy if exists "Anon insert and select access_logs" on public.access_logs;
create policy "Anon full access on access_logs" on public.access_logs
    for all to anon using (true) with check (true);

-- ==============================================================================
-- 4. INSERT DATA 148 PESERTA TERDAFTAR DARI CSV
-- ==============================================================================

on conflict (norm_phone) do update set
    name = excluded.name,
    raw_phone = excluded.raw_phone,
    institution = excluded.institution,
    major = excluded.major,
    proof_url = excluded.proof_url;
